contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, uint256 difficulty_) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(difficulty_ > 0);

        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(amount); if (__ESBMC_reverted()) return;
        c.AdjustDifficulty(difficulty_); if (__ESBMC_reverted()) return;

        c.wager{value: amount}(); if (__ESBMC_reverted()) return;
        require(c.hasPlayerWagered(address(this)));

        bool reverted;
        c.play(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || !c.hasPlayerWagered(address(this)));
    }

    receive() external payable {}
}

