    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount, uint256 difficulty_) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(difficulty_ > 0);
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustBetAmounts(amount) {} catch { return; }
        try c.AdjustDifficulty(difficulty_) {} catch { return; }
        try c.wager{value: amount}() {} catch { return; }
        vm.assume(c.hasPlayerWagered(address(this)));
        bool reverted;
        try c.play() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || !c.hasPlayerWagered(address(this)));
